import{_ as t,o as a,c as i,ag as o}from"./chunks/framework.BcZEdlUI.js";const p=JSON.parse('{"title":"ADR-006: v2.1 架构升级 — 单源真相 + 类型化事件 + DI 现代化","description":"","frontmatter":{},"headers":[],"relativePath":"adr/006-v21-architecture-upgrade.md","filePath":"adr/006-v21-architecture-upgrade.md","lastUpdated":1781612722000}'),n={name:"adr/006-v21-architecture-upgrade.md"};function r(l,e,s,d,c,u){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-006-v2-1-架构升级-—-单源真相-类型化事件-di-现代化" tabindex="-1">ADR-006: v2.1 架构升级 — 单源真相 + 类型化事件 + DI 现代化 <a class="header-anchor" href="#adr-006-v2-1-架构升级-—-单源真相-类型化事件-di-现代化" aria-label="Permalink to &quot;ADR-006: v2.1 架构升级 — 单源真相 + 类型化事件 + DI 现代化&quot;">​</a></h1><ul><li><strong>状态</strong>: ✅ 已接受</li><li><strong>日期</strong>: 2026-06-04</li><li><strong>作者</strong>: 架构团队</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>v2.0 解决了&quot;性能 + 业务能力&quot;（DAG 流水线、短剧特化、FFmpeg 安全加固、审计日志）。但 v2.0 后项目存在<strong>架构债</strong>：</p><ol><li><strong>两个 EventBus 实现并存</strong>：<code>scenefab.core.EventBus</code> 和 <code>scenefab.event_bus.EventBus</code> 各自维护独立 handler 列表 → 同名事件不能跨模块共享</li><li><strong>TaskManager 与 PipelineEngine 无事件桥接</strong>：状态变更靠 Qt Signal，无法跨 CLI/API/Web 共享</li><li><strong>FastAPI router 用私货 <code>_tasks: dict = {}</code></strong>：CLI 跑的任务 Web 看不到</li><li><strong>ServiceContainer 自研</strong>（v1.x 247 行）：缺作用域、缺钩子</li><li><strong>配置分散</strong>（<code>settings.py</code> dataclass + <code>settings_manager.py</code> JSON）：缺类型安全、缺动态重载</li></ol><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to &quot;决策&quot;">​</a></h2><p>v2.1 目标：<strong>用&quot;单源真相 + 类型化事件 + 依赖注入&quot;三大支柱统一运行时骨架</strong>，且 <strong>零破坏</strong>（v1.x 公开 API 100% 兼容）。</p><h3 id="支柱-1-unifiedeventbus-单源真相" tabindex="-1">支柱 1：UnifiedEventBus 单源真相 <a class="header-anchor" href="#支柱-1-unifiedeventbus-单源真相" aria-label="Permalink to &quot;支柱 1：UnifiedEventBus 单源真相&quot;">​</a></h3><ul><li>单一权威实现 <code>scenefab.core.unified_event_bus.UnifiedEventBus</code></li><li>v1.x 两个 EventBus 全部委托到此（薄包装，公开 API 不变）</li><li>全局单例：函数级 <code>_global_bus</code> + 类级 <code>_default_instance</code> <strong>双轨制</strong>，由 <code>set_event_bus()</code> 同步两者</li><li>支持： <ul><li>字符串事件（v1.x 兼容）</li><li><code>DomainEvent</code> 类型化事件（v2.1 强类型）</li><li>sync / async handler 混合</li><li><code>EventLog</code> 内存重放</li><li><code>stats()</code> 可观测</li></ul></li></ul><h3 id="支柱-2-domainevent-强类型" tabindex="-1">支柱 2：DomainEvent 强类型 <a class="header-anchor" href="#支柱-2-domainevent-强类型" aria-label="Permalink to &quot;支柱 2：DomainEvent 强类型&quot;">​</a></h3><p>8 个预定义事件 + 任意自定义：</p><ul><li>Pipeline: <code>PipelineStarted / StepStarted / StepCompleted / PipelineCompleted</code></li><li>Task: <code>TaskCreated / TaskProgressUpdated / TaskStatusChanged</code></li><li>业务: <code>LLMTokenGenerated / FFmpegExecuted</code></li></ul><p><code>TaskManager.create_task / set_status / update_progress</code> 和 <code>PipelineEngine.run / _execute_step</code> 在关键节点发布事件 → 任何订阅者（CLI / FastAPI / WS / 审计）都可观察。</p><h3 id="支柱-3-di-容器-任务存储-事件存储-三件套" tabindex="-1">支柱 3：DI 容器 + 任务存储 + 事件存储 三件套 <a class="header-anchor" href="#支柱-3-di-容器-任务存储-事件存储-三件套" aria-label="Permalink to &quot;支柱 3：DI 容器 + 任务存储 + 事件存储 三件套&quot;">​</a></h3><ul><li><code>DIContainer</code>：v1.x 兼容 + SCOPED 作用域 + 解析钩子 + 全局 <code>get_app_container()</code> 自动注入 event_bus</li><li><code>TaskStore</code>：3 后端 (InMemory / SQLite / Redis) + TTL + 全局共享，FastAPI router 私货 <code>_tasks: dict</code> 替换为 <code>get_task_store()</code></li><li><code>EventStore</code>：3 后端 (InMemory / SQLite / Redis) + 按 event_name / correlation_id 查询 + <code>install_event_store_into_bus()</code> 自动双写</li></ul><h3 id="附加" tabindex="-1">附加 <a class="header-anchor" href="#附加" aria-label="Permalink to &quot;附加&quot;">​</a></h3><ul><li><code>SettingsV2</code> (pydantic-settings)：7 个子配置组，env 自动映射，JSON Schema 生成</li><li><code>WSHub</code>：WebSocket 实时推送，从 UnifiedEventBus 订阅事件分发到连接</li></ul><h2 id="不决策的" tabindex="-1">不决策的 <a class="header-anchor" href="#不决策的" aria-label="Permalink to &quot;不决策的&quot;">​</a></h2><ul><li><strong>不替换 v1.x ServiceContainer</strong>：v2.1 新增 DIContainer 并列存在，旧代码继续工作</li><li><strong>不替换 v1.x Task dataclass</strong>：仍可用，新增 UnifiedTask 作为更现代的替代</li><li><strong>不破坏 v1.x pipeline.py</strong>：保留 <code>PipelineConfig / SceneFabPipeline</code> 公开 API</li></ul><blockquote><p><strong>🟡 状态更新 (2026-06-12)</strong>: 上方 v1.x pipeline 公开 API 已清理. SceneFabPipeline / PipelineConfig / EmotionPeakDetector / FirstPersonExtractor / pipeline.script_generator / pipeline.tts_generator / cli.py / cli/ 包共 2263 行死代码已删除, 由 v2.2 NarrationStateMachine (<a href="/scene-fab/adr/007-narration-state-machine.html">ADR-007</a>) 完全接管解说生成核心流程. 此处历史决策保留作为 v2.1 当时事实记录.</p></blockquote><h2 id="后果" tabindex="-1">后果 <a class="header-anchor" href="#后果" aria-label="Permalink to &quot;后果&quot;">​</a></h2><ul><li>✅ 33/33 v2.0 测试 + 43/43 v2.1 测试全过（76/76 零回归）</li><li>✅ v1.x 公开 API 完全兼容（<code>scenefab.core.EventBus / scenefab.event_bus.EventBus / ApplicationState / ErrorInfo</code> 等）</li><li>✅ 新增 ~3000 行（7 个新 core 模块 + 测试套件）</li><li>⚠️ 引入 pydantic-settings 依赖（已有 requirements.txt，零新增）</li><li>⚠️ FastAPI router 行为完全等价（接口不变，后端换了）</li></ul><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><ul><li>5 篇前作 ADR（001-005）保持不变</li><li>测试：<code>tests/test_arch_v21.py</code>（43 tests, 8 test classes）</li></ul>',24)])])}const g=t(n,[["render",r]]);export{p as __pageData,g as default};
